// FUNCTION: BFME2 0x00741A80 size=60 name=?Prepare_LOD@StreakLineClass@@UAEXAAVCameraClass@@@Z evidence=N:ledger tier=B hypothesis:cohesion
void StreakLineClass::Prepare_LOD(CameraClass &camera)
{
	NormalizedScreenArea = Get_Screen_Size(camera);

	// Ensure subdivision level is legal
	unsigned int lvl = LineRenderer.Get_Current_Subdivision_Level();
	lvl = lvl < MaxSubdivisionLevels ? lvl : MaxSubdivisionLevels;
	LineRenderer.Set_Current_Subdivision_Level(lvl);
}

// FUNCTION: BFME2 0x00741AC0 size=33 name=?Increment_LOD@StreakLineClass@@UAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
void StreakLineClass::Increment_LOD()
{
	unsigned int lvl = LineRenderer.Get_Current_Subdivision_Level();

	lvl = lvl + 1 < MaxSubdivisionLevels ? lvl + 1 : MaxSubdivisionLevels;

	LineRenderer.Set_Current_Subdivision_Level(lvl);
}

// FUNCTION: BFME2 0x00741AF0 size=20 name=?Decrement_LOD@StreakLineClass@@UAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
void StreakLineClass::Decrement_LOD()
{
	int lvl = LineRenderer.Get_Current_Subdivision_Level();
	if (lvl == 0) return;
	LineRenderer.Set_Current_Subdivision_Level(lvl - 1);
}

// FUNCTION: BFME2 0x00741B10 size=82 name=?Get_Value@StreakLineClass@@UBEMXZ evidence=N:ledger tier=B hypothesis:cohesion
float StreakLineClass::Get_Value() const
{
	// If we are at the minimum LOD, we must return AT_MIN_LOD.
	if (LineRenderer.Get_Current_Subdivision_Level() == 0) {
		return 3.4028235e38f;
	} else {
		float polycount = (float)Get_Num_Polys();
		float benefit_factor = 1.0f - (0.5f / (polycount * polycount));
		return (benefit_factor * NormalizedScreenArea) / Get_Cost();
	}
}

// FUNCTION: BFME2 0x00741B70 size=71 name=?Get_Post_Increment_Value@StreakLineClass@@UBEMXZ evidence=N:ledger tier=B hypothesis:cohesion
float StreakLineClass::Get_Post_Increment_Value() const
{
	// If we are at the maximum LOD, we must return AT_MAX_LOD.
	if (LineRenderer.Get_Current_Subdivision_Level() == MaxSubdivisionLevels) {
		return -1.0f;
	} else {
		// Assumption: each subdivision level doubles polycount
		float polycount = 2.0f * (float)Get_Num_Polys();
		float benefit_factor = 1.0f - (0.5f / (polycount * polycount));
		// Assumption: Cost() == polycount
		return (benefit_factor * NormalizedScreenArea) / polycount;
	}
}

// FUNCTION: BFME2 0x00741BC0 size=44 name=?Set_LOD_Level@StreakLineClass@@UAEXH@Z evidence=N:ledger tier=B hypothesis:cohesion
void StreakLineClass::Set_LOD_Level(int lod)
{
	lod = (lod < 0) ? 0 : lod;
	if (lod >= (int)MaxSubdivisionLevels)
		LineRenderer.Set_Current_Subdivision_Level(MaxSubdivisionLevels);
	else
		LineRenderer.Set_Current_Subdivision_Level(lod);
}

