// FUNCTION: BFME2 0x00741D10 size=1653 name=?Get_Obj_Space_Bounding_Box@StreakLineClass@@UBEXAAVAABoxClass@@@Z evidence=N:ledger tier=B hypothesis:cohesion
// FUNCTION: BFME2 0x00742390 size=78 name=?Render_Seg_Line@StreakLineClass@@IAEXAAVRenderInfoClass@@@Z evidence=N:ledger tier=B hypothesis:cohesion
void StreakLineClass::Render_Seg_Line(RenderInfoClass &rinfo)
{
	// Line must have at least two points to be valid
	if (PointLocations.Count() < 2) return;

	SphereClass bounding_sphere;
	Get_Obj_Space_Bounding_Sphere(bounding_sphere);

	LineRenderer.Render(rinfo, Transform, PointLocations.Count(), &(PointLocations[0]), bounding_sphere);
}

// FUNCTION: BFME2 0x007423E0 size=129 name=?Render_Streak_Line@StreakLineClass@@IAEXAAVRenderInfoClass@@@Z evidence=N:ledger tier=B hypothesis:cohesion
void StreakLineClass::Render_Streak_Line(RenderInfoClass &rinfo)
{
	// Line must have at least two points to be valid
	if (PointLocations.Count() < 2) return;
	if (PointColors.Count() < 2) return;
	if (PointWidths.Count() < 2) return;

	if (PointLocations.Count() != PointColors.Count()) return;
	if (PointLocations.Count() != PointWidths.Count()) return;

	SphereClass bounding_sphere;
	Get_Obj_Space_Bounding_Sphere(bounding_sphere);

	StreakRenderer.RenderStreak(
		rinfo,
		Transform,
		PointLocations.Count(),
		&(PointLocations[0]),
		&(PointColors[0]),
		&(PointWidths[0]),
		bounding_sphere,
		Personalities
		);
}

